 if exists(select 1 from public.sales) or exists(select 1 from public.cash_accounts) or exists(select 1 from public.debt_entries) then raise exception 'owner RLS widened';end if;
 x:=public.get_manager_sales_report(current_setting('mg.owner')::uuid,today,today);
 if x->>'count'<>'4' or x->>'sales_total'<>'1900' or x->>'returns_total'<>'1450' or x->>'net_total'<>'450' or x->>'cash_net'<>'450' or x->>'debt_net'<>'0' or x->>'discounts'<>'100' or x->>'actor_id'<>auth.uid()::text then raise exception 'manager event arithmetic or identity';end if;
 x:=public.get_manager_receipt(current_setting('mg.owner')::uuid,current_setting('mg.cash')::uuid);if x->'returns'->>'total'<>'450' or x->'sale'->>'actor_id'<>current_setting('mg.owner') or x->'sale'->>'id'<>current_setting('mg.cash') then raise exception 'other actor receipt unavailable';end if;
 x:=public.get_manager_receipt(current_setting('mg.owner')::uuid,current_setting('mg.credit')::uuid);if x->'returns'->>'full'<>'true' or x->'returns'->>'debt_reversed'<>'800' or x->'returns'->>'cash_refund'<>'200' then raise exception 'credit/full receipt state';end if;
 if auth.uid()<>current_setting('mg.member')::uuid then raise exception 'JWT impersonation';end if;
 begin perform public.get_manager_sales_report(current_setting('mg.owner')::uuid,today,today+366);raise exception 'range accepted';exception when raise_exception then if sqlerrm<>'manager_invalid_range' then raise;end if;end;
 begin perform public.get_manager_receipt(current_setting('mg.owner')::uuid,gen_random_uuid());raise exception 'foreign sale';exception when raise_exception then if sqlerrm<>'staff_sale_unavailable' then raise;end if;end;
end $$;
